/**
 * Bibliography database — CSL-JSON as authoritative source.
 *
 * This file replaces `references.bib` as the source of truth.
 * BibTeX is now a downstream render target, generated by
 * `pipeline/export-bibtex.ts`.
 *
 * ## Where the entries live (bean qou-l7pj, owner 2026-10-14 "1 + 2")
 *
 * Each entry is its own file, `folio/references/<id>.json`: the CSL-JSON
 * item exactly as it used to be written here, with
 * `"$schema": "folio-reference/v1"` as its first key. The directory is
 * declared in `qou.json` with graph typology `references`, so the platform's
 * bibliography viewer reads it as Reference nodes.
 *
 * This module is now a thin loader. It reads every file named in
 * {@link ORDER}, validates each with `ref()` (the Zod check below), and
 * exports the same `references` array, `referenceMap`, `getRef` and
 * `allRefIds` as before, so every importer works unchanged.
 *
 * Two kinds of key a file may carry besides the CSL item:
 * - `$schema` — the node schema tag; dropped on load;
 * - `_comment` — an array of note lines for a person reading the file. These
 *   are the `//` comments that sat inside the entry when it was written here.
 *   Every top-level `_` key is dropped on load, as the platform's
 *   `toCslItem` does, so `references` holds exactly the CSL item.
 *
 * ## Order is kept by ORDER, below
 *
 * `references.bib` is emitted in array order, so the order is part of the
 * output. {@link ORDER} lists every entry, one `{ id: <key> }` line each
 * (the key a double-quoted string),
 * in the order the array had. The comments between entries stayed where
 * they were. The loader is strict: an id listed twice, a listed id with no
 * file, or a file that ORDER does not list is an error at import. A
 * directory listing alone would sort by file name and reorder the `.bib`.
 *
 * The `id:` spelling is kept on purpose. Text scanners collect keys by
 * matching `id:` plus a quoted string in this file, for example the platform's
 * `bib-cite-resolves` checker (`qa-checkers-extended.ts` `loadBibIdSet`) and
 * `scripts/check-citation-keys.py`. Keeping that spelling keeps those
 * scanners working.
 *
 * ## Adding an entry
 *
 * 1. Write `folio/references/<id>.json` with `"$schema": "folio-reference/v1"`
 *    and the CSL fields.
 * 2. Add a `{ id: <id> },` line to ORDER, where it should appear in
 *    `references.bib`. New entries usually go at the end.
 *
 * Fields follow the CSL-JSON spec: https://citeproc-js.readthedocs.io/en/latest/csl-json/markup.html
 *
 * ## Entries built by code
 *
 * An entry whose values are computed cannot be a static JSON file. Such an
 * entry stays here as a `ref({...})` call inside ORDER, at its place in the
 * order. There is one: `leitner2026`, the self-citation. Its title, author and
 * year come from `paperIdentity`.
 *
 * ## Key convention
 *
 * Each entry's `id` follows the BibTeX key convention:
 *   <firstauthorlastname><year>  (all lower-case)
 *   e.g. chenier2026, einstein1905
 *
 * ## Downstream consumers
 *
 * - `pipeline/export-bibtex.ts` → `references.bib` (for LaTeX)
 * - `pipeline/validate-references.ts` → cross-checks against Lean `-- Ref:` comments
 * - `pipeline/export-json.ts` → `references.json` (for viewer/MCP)
 * - Content blocks may reference entries by `id` in `uses[]` or `meta.cites[]`
 * - `scripts/sync-references-library.py` writes the `library` block of each
 *   `folio/references/<id>.json`
 * - Python scanners read the directory through `scripts/lib/references_dir.py`
 *
 * @module folio/schema/references
 */

import { readFileSync, readdirSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { z } from "zod";
import type { Data as CSLData, Person as CSLPerson, Date as CSLDate, ItemType } from "csl-json";
import { paperIdentity } from "../quantum-observable-universe/identity";

// ── Re-exports for consumer convenience ─────────────────────────
export type { CSLData, CSLPerson, CSLDate, ItemType };

/**
 * Where our copy of a source is, and how far it has been processed.
 *
 * Written into each `folio/references/<id>.json` by
 * `scripts/sync-references-library.py`, and
 * derived entirely from the library tree plus the source ledger — never
 * authored, never hand-edited. The field order here matches that script's
 * `render()` so a regenerated block diffs cleanly.
 *
 * Declared because `CSLData` from the `csl-json` package does not have it,
 * and 351 entries carry it. The Zod schema is `.passthrough()`, so this was
 * valid at runtime and rejected by the compiler — 712 `TS2353` errors,
 * invisible because nothing type-checks this file: qou has no `tsc` gate on
 * it, and the platform's `tsc` only sees it through the bridge symlink that
 * `setup-folio-assistant.sh` creates in a working clone and CI does not have.
 */
export interface LibraryRef {
  /** Directory name under `library/`, and the join key to the source ledger. */
  docId: string;
  dir: string;
  pdf?: string;
  /** A path the ledger claims we hold that is not in the repo. */
  claimedPath?: string;
  /** How far ingestion got: held < structure < sections < candidates, or `missing`. */
  stage: "held" | "structure" | "sections" | "candidates" | "missing";
  pages?: number;
  sections?: number;
  arxiv?: string;
  /** Other copies of the same work, when the join landed on a duplicate. */
  alternates?: string[];
  duplicateOf?: string;
}

/**
 * A CSL-JSON entry plus the derived record of the copy we hold.
 *
 * `series` is here because the `csl-json` package's `Data` omits it while
 * entries use it for a journal's series designation — `rogers1907` is
 * Proc. LMS **series 2**, vol. 4 — and dropping it to satisfy the compiler
 * would lose the only thing distinguishing that volume from the first
 * series' volume 4.
 */
export type Reference = CSLData & {
  library?: LibraryRef;
  series?: string;
};

// ── Zod schema for CSL-JSON validation ──────────────────────────

const CSLPersonSchema = z.object({
  family: z.string().optional(),
  given: z.string().optional(),
  suffix: z.string().optional(),
  "non-dropping-particle": z.string().optional(),
  "dropping-particle": z.string().optional(),
  literal: z.string().optional(),
}).refine(
  (p) => p.family || p.literal,
  { message: "Person must have either `family` or `literal` name" },
);

const CSLDateSchema = z.object({
  "date-parts": z.array(
    z.tuple([z.union([z.string(), z.number()])]).rest(z.union([z.string(), z.number()]).optional()),
  ).optional(),
  raw: z.string().optional(),
  literal: z.string().optional(),
  season: z.union([z.number(), z.string()]).optional(),
  circa: z.boolean().optional(),
}).refine(
  (d) => d["date-parts"] || d.raw || d.literal,
  { message: "Date must have `date-parts`, `raw`, or `literal`" },
);

export const CSLItemTypeSchema = z.enum([
  "article", "article-journal", "article-magazine", "article-newspaper",
  "bill", "book", "broadcast", "chapter", "dataset", "entry",
  "entry-dictionary", "entry-encyclopedia", "figure", "graphic",
  "interview", "legal_case", "legislation", "manuscript", "map",
  "motion_picture", "musical_score", "pamphlet", "paper-conference",
  "patent", "personal_communication", "post", "post-weblog",
  "report", "review", "review-book", "song", "speech", "thesis",
  "treaty", "webpage",
]);

export const CSLEntrySchema = z.object({
  id: z.string().min(1, "Entry must have an id"),
  type: CSLItemTypeSchema,
  title: z.string().min(1, "Entry must have a title"),

  // Person fields
  author: z.array(CSLPersonSchema).optional(),
  editor: z.array(CSLPersonSchema).optional(),
  translator: z.array(CSLPersonSchema).optional(),
  "collection-editor": z.array(CSLPersonSchema).optional(),
  "container-author": z.array(CSLPersonSchema).optional(),

  // Date fields
  issued: CSLDateSchema.optional(),
  accessed: CSLDateSchema.optional(),
  "original-date": CSLDateSchema.optional(),

  // String fields
  "container-title": z.string().optional(),
  "collection-title": z.string().optional(),
  publisher: z.string().optional(),
  "publisher-place": z.string().optional(),
  page: z.string().optional(),
  DOI: z.string().optional(),
  URL: z.string().optional(),
  ISBN: z.string().optional(),
  ISSN: z.string().optional(),
  note: z.string().optional(),
  abstract: z.string().optional(),
  genre: z.string().optional(),
  number: z.union([z.string(), z.number()]).optional(),

  // Number fields
  volume: z.union([z.string(), z.number()]).optional(),
  issue: z.union([z.string(), z.number()]).optional(),
  edition: z.union([z.string(), z.number()]).optional(),
  "chapter-number": z.union([z.string(), z.number()]).optional(),
  "collection-number": z.union([z.string(), z.number()]).optional(),
  "number-of-pages": z.union([z.string(), z.number()]).optional(),
  "number-of-volumes": z.union([z.string(), z.number()]).optional(),
}).passthrough();

// ── Builder ─────────────────────────────────────────────────────

/** Validates a CSL-JSON entry at construction time. */
export function ref(data: Reference): Reference {
  CSLEntrySchema.parse(data);
  return data;
}


// ── Loading the per-entry files ─────────────────────────────────

/** The schema tag every `folio/references/<id>.json` carries as its first key. */
export const REFERENCE_SCHEMA_TAG = "folio-reference/v1";

/** `folio/references/`, the declared `references` directory (qou.json). */
export const REFERENCES_DIR = join(dirname(fileURLToPath(import.meta.url)), "..", "references");

/** A slot in ORDER filled from `folio/references/<id>.json`. */
type FileSlot = { id: string };

/** A slot that is only `{ id }` names a file; any other slot is a `ref()` built here. */
function isBuiltHere(slot: FileSlot | Reference): slot is Reference {
  return Object.keys(slot).length > 1;
}

/** Read one entry file, drop `$schema` and the `_` note keys, and validate it with `ref()`. */
function loadReferenceFile(id: string): Reference {
  const path = join(REFERENCES_DIR, `${id}.json`);
  let raw: Record<string, unknown>;
  try {
    raw = JSON.parse(readFileSync(path, "utf-8"));
  } catch (e) {
    throw new Error(`folio/references/${id}.json: ${(e as Error).message}`);
  }
  if (raw.$schema !== REFERENCE_SCHEMA_TAG) {
    throw new Error(`folio/references/${id}.json: "$schema" must be "${REFERENCE_SCHEMA_TAG}"`);
  }
  if (raw.id !== id) {
    throw new Error(`folio/references/${id}.json: the file is named for "${id}" but its id is ${JSON.stringify(raw.id)}`);
  }
  const entry = Object.fromEntries(
    Object.entries(raw).filter(([k]) => k !== "$schema" && !k.startsWith("_")),
  ) as Reference;
  try {
    return ref(entry);
  } catch (e) {
    throw new Error(`folio/references/${id}.json: ${(e as Error).message}`);
  }
}

/** ORDER, resolved: every slot loaded, in order; strict about missing, duplicate and unlisted files. */
function assemble(order: Array<FileSlot | Reference>): Reference[] {
  const onDisk = new Set(
    readdirSync(REFERENCES_DIR).filter((f) => f.endsWith(".json")).map((f) => f.slice(0, -".json".length)),
  );
  const seen = new Set<string>();
  const out = order.map((slot) => {
    if (seen.has(slot.id)) throw new Error(`references.ts ORDER lists "${slot.id}" twice`);
    seen.add(slot.id);
    if (isBuiltHere(slot)) {
      if (onDisk.has(slot.id)) {
        throw new Error(`"${slot.id}" is built in references.ts and also has folio/references/${slot.id}.json; keep one`);
      }
      return slot;
    }
    if (!onDisk.has(slot.id)) throw new Error(`references.ts ORDER lists "${slot.id}" but folio/references/${slot.id}.json does not exist`);
    return loadReferenceFile(slot.id);
  });
  const unlisted = [...onDisk].filter((id) => !seen.has(id)).sort();
  if (unlisted.length) {
    throw new Error(
      `folio/references/ holds ${unlisted.length} file(s) that references.ts ORDER does not list: ${unlisted.join(", ")}. ` +
        "Add a { id: <key> } line to ORDER where the entry belongs in references.bib.",
    );
  }
  return out;
}

