export const references: Reference[] = assemble(ORDER);

// ── Lookup helpers ──────────────────────────────────────────────

/** Map from id → entry for O(1) lookup. */
export const referenceMap = new Map(references.map((r) => [r.id, r]));

/** Get a reference by id. Throws if not found. */
export function getRef(id: string): Reference {
  const entry = referenceMap.get(id);
  if (!entry) throw new Error(`Unknown reference: "${id}". Check folio/references/ and ORDER in folio/schema/references.ts`);
  return entry;
}

/** All known reference ids. */
export function allRefIds(): string[] {
  return references.map((r) => r.id);
}
